const payload = outputs.fetch_orders && outputs.fetch_orders.data ? outputs.fetch_orders.data : {};
const orders = Array.isArray(payload.orders) ? payload.orders : [];
let revenue = 0;
let cancelled = 0;
for (const order of orders) {
  const total = Number(order.total_price || order.total_price_usd || 0);
  if (Number.isFinite(total)) revenue += total;
  const status = String(order.cancel_reason || order.cancelled_status || order.financial_status || '').toLowerCase();
  if (status.includes('cancel') || status.includes('refund')) cancelled += 1;
}
const language = String(input || 'vi').toLowerCase();
const amount = Math.round(revenue * 100) / 100;
const message = language === 'en'
  ? `Haravan daily report | Orders fetched: ${orders.length} | Order value: ${amount} | Cancel/refund signals: ${cancelled}`
  : `Báo cáo Haravan | Đơn đã lấy: ${orders.length} | Tổng giá trị đơn: ${amount} | Tín hiệu hủy/hoàn: ${cancelled}`;
return { order_count: orders.length, order_value: amount, cancelled_refunded_signals: cancelled, message };

const recipient = String(input || '').trim();
if (!recipient) throw new Error('Zalo recipient is required');
const message = String(outputs.aggregate && outputs.aggregate.message ? outputs.aggregate.message : '');
return { body: JSON.stringify({ recipient_id: recipient, message }) };
